def backtrack(nums, start, path, res):
    res.append(path[:])
    for i in range(start, len(nums)):
        if i > start and nums[i] == nums[i-1]:
            continue  # 树层去重：同层跳过重复值
        path.append(nums[i])
        backtrack(nums, i + 1, path, res)
        path.pop()

