# 滑动窗口版：仅当 nums 全为非负数时正确（含负数会漏解）
def subarraySum_nonneg(nums, k):
    count = 0
    left = 0
    window = 0
    for right, x in enumerate(nums):
        window += x
        while window > k and left <= right:
            window -= nums[left]
            left += 1
        if window == k:
            count += 1
    return count

